import { useEffect, useMemo, useState } from "react";
import {
  Activity, ArrowLeft, ArrowUpLeft, Bell, CalendarDays, Camera, Check, ChevronDown, Clock3,
  FileDown, FileText, HeartPulse, ImagePlus, LayoutDashboard, Mail, Menu, MessageCircle, MoreHorizontal,
  Paperclip, Plus, QrCode, ReceiptText, Search, Settings2, ShieldCheck, Stethoscope,
  UserRound, UsersRound, WalletCards, X, Zap,
} from "lucide-react";
import CameraCapture from "@/components/CameraCapture";
import PatientModal from "@/components/PatientModal";
import { formatArabicDate, openWhatsApp, useClinicData } from "@/lib/clinicStore";
import { openPrintableHtml, printMedicalDocument, printMedicalRecordReport } from "@/lib/printTemplates";

const NAV_ITEMS = [
  { id: "dashboard", label: "نظرة عامة", icon: LayoutDashboard },
  { id: "patients", label: "المرضى والسجلات", icon: UsersRound, asset: "/public/assets/patient-folder.jpg" },
  { id: "diagnosis", label: "تشخيص الطبيب", icon: Stethoscope, asset: "/public/assets/doctor-diagnosis.jpg" },
  { id: "reminders", label: "تذكيرات المراجعة", icon: Bell, asset: "/public/assets/appointment-calendar.svg", badge: "reminders" },
  { id: "appointments", label: "المواعيد والحجوزات", icon: CalendarDays, asset: "/public/assets/appointment-calendar.svg", badge: 5 },
  { id: "billing", label: "الحسابات الطبية", icon: WalletCards, asset: "/public/assets/invoice-billing.jpg" },
  { id: "prescriptions", label: "الروشتات والتقارير", icon: FileText, asset: "/public/assets/prescription.jpg" },
];

const PAGE_META = {
  dashboard: { title: "نظرة عامة", subtitle: "صباح الخير، د. ليان. إليك ملخص يوم العيادة." },
  patients: { title: "المرضى والسجلات", subtitle: "إدارة ملفات المرضى والوصول السريع إلى التاريخ الطبي." },
  diagnosis: { title: "تشخيص الطبيب", subtitle: "سجّل الفحص السريري ونتائج التحاليل وخطة العلاج داخل ملف المريض." },
  reminders: { title: "تذكيرات المراجعة", subtitle: "تابع مواعيد المراجعة القادمة وأرسل تذكيراً سريعاً للمريض." },
  appointments: { title: "المواعيد والحجوزات", subtitle: "نظّم جدول الأطباء وتابع حالة الحضور لحظة بلحظة." },
  billing: { title: "الحسابات الطبية", subtitle: "كشف الزيارة والخروج والتحاليل في مستندات مالية واضحة." },
  prescriptions: { title: "الروشتات والتقارير", subtitle: "الوصفات الطبية والتقارير الصادرة من العيادة." },
  settings: { title: "إعدادات العيادة", subtitle: "بيانات العيادة محفوظة تلقائياً ولا تحتاج إلى تفعيل يدوي." },
};

function Sidebar({ active, onNavigate, mobileOpen, onClose, isOnline, reminderCount }) {
  return <>
    {mobileOpen && <button className="fixed inset-0 z-30 bg-slate-950/30 lg:hidden" onClick={onClose} aria-label="إغلاق القائمة" />}
    <aside className={`fixed inset-y-0 right-0 z-40 flex w-[268px] flex-col border-l border-slate-200/70 bg-white/95 px-4 py-5 shadow-[0_12px_48px_rgba(15,23,42,0.05)] backdrop-blur transition-transform duration-200 lg:translate-x-0 ${mobileOpen ? "translate-x-0" : "translate-x-full"}`}>
      <div className="flex items-center gap-3 px-3 pb-7"><span className="brand-mark"><img src="/public/assets/clinic-mark.jpg" alt="" className="brand-mark-image" /></span><div><p className="text-[15px] font-extrabold tracking-tight text-slate-900">عيادتي</p><p className="text-[10px] font-bold text-slate-400">نظام الإدارة الطبية</p></div><button onClick={onClose} className="icon-button mr-auto lg:hidden"><X size={18} /></button></div>
      <div className="mb-3 px-3 text-[10px] font-extrabold uppercase tracking-[0.18em] text-slate-400">مساحة العمل</div>
      <nav className="space-y-1">{NAV_ITEMS.map(({ id, label, icon: Icon, asset, badge }) => <button key={id} onClick={() => { onNavigate(id); onClose(); }} className={`nav-item ${active === id ? "nav-item-active" : ""}`}>{asset ? <img src={asset} alt="" className="nav-asset-icon" /> : <Icon size={18} strokeWidth={active === id ? 2.3 : 1.9} />}<span>{label}</span>{badge && <span className="nav-badge">{badge === "reminders" ? reminderCount : badge}</span>}</button>)}</nav>
      <div className="my-6 h-px bg-slate-100" />
      <button onClick={() => { onNavigate("settings"); onClose(); }} className={`nav-item ${active === "settings" ? "nav-item-active" : ""}`}><Settings2 size={18} /><span>بيانات العيادة</span></button>
      <div className="mt-auto rounded-2xl bg-slate-900 p-4 text-white"><div className="mb-4 flex items-center justify-between"><span className="grid h-9 w-9 place-items-center rounded-xl bg-white/10 text-teal-300"><ShieldCheck size={19} /></span><span className={`status-dot ${isOnline ? "status-dot-online" : "status-dot-offline"}`} /></div><p className="text-xs font-bold text-white/60">الحفظ التلقائي</p><p className="mt-1 text-sm font-extrabold">{isOnline ? "محفوظ ويعمل تلقائياً" : "محفوظ على الجهاز"}</p><p className="mt-3 text-[11px] leading-5 text-white/45">كل تغيير يُحفظ تلقائياً على جهازك ويستمر العمل عند انقطاع الإنترنت.</p></div>
      <div className="mt-4 flex items-center gap-3 px-2"><div className="avatar avatar-teal">لل</div><div className="min-w-0 flex-1"><p className="truncate text-xs font-extrabold text-slate-800">د. ليان السالم</p><p className="text-[10px] font-medium text-slate-400">مديرة العيادة</p></div><MoreHorizontal size={17} className="text-slate-400" /></div>
    </aside>
  </>;
}

function Header({ meta, isOnline, onMenu, onBack, canGoBack, onCamera }) {
  return <header className="sticky top-0 z-20 border-b border-slate-200/70 bg-[#f6f9fc]/90 px-4 py-4 backdrop-blur-xl sm:px-7 lg:px-10"><div className="flex items-center gap-3"><button onClick={canGoBack ? onBack : onMenu} className="icon-button lg:hidden" aria-label={canGoBack ? "الرجوع للصفحة السابقة" : "فتح القائمة"}>{canGoBack ? <ArrowLeft size={20} /> : <Menu size={20} />}</button><div className="min-w-0 flex-1"><div className="flex items-center gap-2"><h1 className="truncate text-xl font-extrabold tracking-tight text-slate-950 sm:text-2xl">{meta.title}</h1><span className="hidden rounded-full bg-teal-50 px-2 py-1 text-[10px] font-extrabold text-teal-700 sm:inline">اليوم، 24 سبتمبر 2026</span></div><p className="mt-1 truncate text-xs font-medium text-slate-500 sm:text-sm">{meta.subtitle}</p></div><div className="hidden items-center gap-2 md:flex"><span className={`connection-pill ${isOnline ? "connection-online" : "connection-offline"}`}><span className="status-dot" />{isOnline ? "حفظ تلقائي" : "محفوظ على الجهاز"}</span><button className="icon-button relative" aria-label="الإشعارات"><Bell size={18} /><span className="notification-dot" /></button><button onClick={onCamera} className="secondary-button !hidden xl:!flex"><Camera size={16} /> صورة ملف / QR</button><button className="primary-button"><Plus size={16} /> إجراء سريع</button></div><button className="icon-button md:hidden" aria-label="الإشعارات"><Bell size={18} /><span className="notification-dot" /></button></div></header>;
}

function StatCard({ label, value, delta, icon: Icon, tone = "teal", note }) {
  return <div className="panel stat-card"><div className="flex items-start justify-between"><span className={`stat-icon stat-icon-${tone}`}><Icon size={19} /></span><span className={delta?.startsWith("-") ? "delta-negative" : "delta-positive"}>{delta}</span></div><div className="mt-5"><p className="text-xs font-bold text-slate-500">{label}</p><p className="mt-1 text-2xl font-extrabold tracking-tight text-slate-950">{value}</p>{note && <p className="mt-1 text-[11px] font-medium text-slate-400">{note}</p>}</div></div>;
}

function StatusBadge({ value }) { const styles = { "مؤكد": "badge-success", "في الانتظار": "badge-warning", "ملغي": "badge-danger", "مدفوعة": "badge-success", "معلقة": "badge-warning", "متابعة": "badge-info", "مستقر": "badge-success", "جديدة": "badge-purple" }; return <span className={`status-badge ${styles[value] || "badge-neutral"}`}><span className="h-1.5 w-1.5 rounded-full bg-current" />{value}</span>; }
function Avatar({ name, tone = "teal" }) { return <span className={`avatar avatar-${tone}`}>{name.split(" ").slice(0, 2).map((part) => part[0]).join("")}</span>; }

function DashboardView({ data, onNavigate, onCamera }) {
  const todayAppointments = data.appointments.filter((item) => item.date === "2026-09-24");
  const paid = data.bills.filter((bill) => bill.status === "مدفوعة").reduce((sum, bill) => sum + bill.amount, 0);
  return <div className="space-y-6 animate-enter"><section className="hero-panel"><div className="relative z-10 max-w-lg"><span className="eyebrow-pill"><Zap size={13} fill="currentColor" /> مركز نبض الطبي</span><h2 className="mt-4 text-2xl font-extrabold leading-tight tracking-tight text-slate-950 sm:text-[30px]">كل تفاصيل العيادة،<br /><span className="text-teal-600">في مكان واحد.</span></h2><p className="mt-3 max-w-md text-sm font-medium leading-6 text-slate-500">تابع زيارات اليوم، آخر السجلات والتنبيهات المهمة لتبقى على اطلاع دائم.</p><div className="mt-5 flex flex-wrap gap-2"><button onClick={() => onNavigate("appointments")} className="primary-button">عرض جدول اليوم <ArrowLeft size={16} /></button><button onClick={onCamera} className="secondary-button"><QrCode size={16} /> حضور بصورة أو QR</button></div></div><div className="hero-orbit hero-orbit-one" /><div className="hero-orbit hero-orbit-two" /><div className="hero-pulse"><Activity size={25} /></div><div className="hero-mini-card hero-mini-card-top"><span className="text-[10px] font-bold text-slate-400">معدل رضا المرضى</span><strong>96.8%</strong><span className="text-[10px] font-bold text-emerald-600">+4.2%</span></div><div className="hero-mini-card hero-mini-card-bottom"><span className="grid h-7 w-7 place-items-center rounded-lg bg-emerald-100 text-emerald-600"><Check size={15} /></span><div><p className="text-[10px] font-bold text-slate-400">تقدم اليوم</p><strong className="text-sm text-slate-800">18 / 24 زيارة</strong></div></div></section><section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="إجمالي المرضى" value={data.patients.length.toLocaleString("ar-SA")} delta="+12.5%" icon={UsersRound} tone="teal" note="مقارنة بالشهر الماضي" /><StatCard label="مواعيد اليوم" value={todayAppointments.length.toLocaleString("ar-SA")} delta="+8.2%" icon={CalendarDays} tone="blue" note="من 24 موعداً مجدولاً" /><StatCard label="المحصّل الطبي" value={`${paid.toLocaleString("ar-SA")} ر.س`} delta="+14.8%" icon={WalletCards} tone="amber" note="حتى 24 سبتمبر" /><StatCard label="متوسط الانتظار" value="12 دقيقة" delta="-18.4%" icon={Clock3} tone="purple" note="تحسن عن الأسبوع الماضي" /></section><section className="grid gap-5 xl:grid-cols-[1.35fr_0.9fr]"><div className="panel overflow-hidden"><div className="panel-heading"><div><h3 className="section-title">مواعيد اليوم</h3><p className="section-subtitle">الخميس، 24 سبتمبر · 5 حجوزات</p></div><button onClick={() => onNavigate("appointments")} className="text-button">عرض الكل <ArrowLeft size={14} /></button></div><div className="divide-y divide-slate-100">{todayAppointments.slice(0, 4).map((appointment, index) => <div key={appointment.id} className="appointment-row"><div className="time-column"><span>{appointment.time}</span><i /></div><Avatar name={appointment.patientName} tone={["teal", "blue", "amber", "purple"][index % 4]} /><div className="min-w-0 flex-1"><p className="truncate text-sm font-extrabold text-slate-800">{appointment.patientName}</p><p className="mt-1 truncate text-xs font-medium text-slate-400">{appointment.type} · {appointment.doctor}</p></div><StatusBadge value={appointment.status} /><button onClick={() => openWhatsApp(appointment.phone, `مرحباً ${appointment.patientName}، نذكركم بموعدكم في ${appointment.time} لدى مركز نبض الطبي.`)} className="icon-button hidden sm:flex"><MessageCircle size={16} /></button></div>)}</div></div><div className="panel"><div className="panel-heading"><div><h3 className="section-title">نشاط العيادة</h3><p className="section-subtitle">آخر 7 أيام</p></div></div><div className="flex h-40 items-end gap-2 px-2 pb-3 pt-5">{[42, 58, 46, 72, 63, 86, 69].map((height, index) => <div key={index} className="flex flex-1 flex-col items-center gap-2"><div className={`chart-bar ${index === 5 ? "chart-bar-active" : ""}`} style={{ height: `${height}%` }}><span>{index === 5 ? "24" : ""}</span></div><span className="text-[10px] font-bold text-slate-400">{["سبت", "أحد", "اثن", "ثلا", "أرب", "خمي", "جمع"][index]}</span></div>)}</div><div className="mt-3 flex items-center justify-between border-t border-slate-100 pt-4"><div><p className="text-xs font-bold text-slate-400">إجمالي الزيارات</p><p className="mt-1 text-lg font-extrabold text-slate-900">١٤٢ زيارة</p></div><span className="delta-positive">+12.5%</span></div></div></section><section className="grid gap-5 lg:grid-cols-[1fr_1fr_0.8fr]"><div className="panel"><div className="panel-heading"><div><h3 className="section-title">إجراءات سريعة</h3><p className="section-subtitle">اختصارات العمل اليومية</p></div></div><div className="grid grid-cols-2 gap-2"><button onClick={() => onNavigate("patients")} className="quick-action"><span className="quick-icon bg-teal-50 text-teal-600"><UserRound size={17} /></span><span>مريض جديد</span><ArrowUpLeft size={14} /></button><button onClick={() => onNavigate("appointments")} className="quick-action"><span className="quick-icon bg-blue-50 text-blue-600"><CalendarDays size={17} /></span><span>حجز موعد</span><ArrowUpLeft size={14} /></button><button onClick={onCamera} className="quick-action"><span className="quick-icon bg-amber-50 text-amber-600"><Camera size={17} /></span><span>صورة ملف / QR</span><ArrowUpLeft size={14} /></button><button onClick={() => onNavigate("billing")} className="quick-action"><span className="quick-icon bg-purple-50 text-purple-600"><ReceiptText size={17} /></span><span>حساب طبي</span><ArrowUpLeft size={14} /></button></div></div><div className="panel"><div className="panel-heading"><div><h3 className="section-title">آخر المرضى</h3><p className="section-subtitle">تمت زيارتهم مؤخراً</p></div><button onClick={() => onNavigate("patients")} className="text-button">كل المرضى <ArrowLeft size={14} /></button></div><div className="space-y-3">{data.patients.slice(0, 4).map((patient, index) => <div key={patient.id} className="flex items-center gap-3"><Avatar name={patient.name} tone={["teal", "blue", "amber", "purple"][index % 4]} /><div className="min-w-0 flex-1"><p className="truncate text-xs font-extrabold text-slate-800">{patient.name}</p><p className="text-[10px] font-medium text-slate-400">{formatArabicDate(patient.lastVisit)}</p></div><StatusBadge value={patient.status} /></div>)}</div></div><div className="panel flex flex-col justify-between bg-slate-900 text-white"><div><span className="grid h-10 w-10 place-items-center rounded-2xl bg-teal-400/15 text-teal-300"><Stethoscope size={20} /></span><h3 className="mt-5 text-lg font-extrabold">تذكير المواعيد</h3><p className="mt-2 text-xs font-medium leading-6 text-white/60">أرسل تذكيرات الموعد قبل 24 ساعة لتقليل حالات عدم الحضور.</p></div><button onClick={() => openWhatsApp("966501234567", "مرحباً، هذا تذكير من مركز نبض الطبي بموعدكم القادم.")} className="mt-6 flex items-center justify-between rounded-xl bg-white/10 px-3 py-2.5 text-xs font-extrabold text-white transition hover:bg-white/15">إرسال تذكير <MessageCircle size={15} className="text-teal-300" /></button></div></section></div>;
}

function PatientsView({ data, onAdd, onCamera }) { const [query, setQuery] = useState(""); const [selected, setSelected] = useState(null); const filtered = data.patients.filter((patient) => `${patient.name} ${patient.id} ${patient.phone}`.toLowerCase().includes(query.toLowerCase())); return <div className="space-y-5 animate-enter"><div className="panel flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between"><div><h2 className="section-title">ملفات المرضى</h2><p className="section-subtitle">{data.patients.length} ملفاً نشطاً في قاعدة البيانات المحلية</p></div><div className="flex flex-wrap gap-2"><button onClick={onCamera} className="secondary-button"><Camera size={16} /> صورة ملف / QR</button><button onClick={onAdd} className="primary-button"><Plus size={16} /> إضافة مريض</button></div></div><div className="panel p-0"><div className="flex flex-col gap-3 border-b border-slate-100 p-4 sm:flex-row sm:items-center sm:justify-between"><div className="search-box"><Search size={17} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="ابحث بالاسم أو رقم الملف..." /></div><div className="flex items-center gap-2 text-xs font-bold text-slate-400"><span className="hidden sm:inline">ترتيب حسب:</span><button className="filter-button">آخر زيارة <ChevronDown size={14} /></button></div></div><div className="hidden overflow-x-auto md:block"><table className="data-table"><thead><tr><th>المريض</th><th>رقم الملف</th><th>البيانات الأساسية</th><th>آخر زيارة</th><th>الحالة</th><th /></tr></thead><tbody>{filtered.map((patient, index) => <tr key={patient.id} onClick={() => setSelected(patient)} className="cursor-pointer"><td><div className="flex items-center gap-3"><Avatar name={patient.name} tone={["teal", "blue", "amber", "purple"][index % 4]} /><div><p className="font-extrabold text-slate-800">{patient.name}</p><p className="mt-0.5 text-[11px] text-slate-400">{patient.gender} · {patient.age} سنة</p></div></div></td><td><span className="font-mono text-xs font-bold text-slate-500">{patient.id}</span></td><td><div className="flex items-center gap-2"><span className="blood-pill">{patient.bloodType}</span><div className="flex gap-1">{patient.tags.slice(0, 2).map((tag) => <span key={tag} className="tag-pill">{tag}</span>)}</div></div></td><td><span className="text-xs font-bold text-slate-600">{formatArabicDate(patient.lastVisit)}</span></td><td><StatusBadge value={patient.status} /></td><td><button className="icon-button"><MoreHorizontal size={17} /></button></td></tr>)}</tbody></table></div><div className="space-y-2 p-3 md:hidden">{filtered.map((patient, index) => <button key={patient.id} onClick={() => setSelected(patient)} className="flex w-full items-center gap-3 rounded-2xl border border-slate-100 p-3 text-right"><Avatar name={patient.name} tone={["teal", "blue", "amber", "purple"][index % 4]} /><div className="min-w-0 flex-1"><p className="truncate text-sm font-extrabold text-slate-800">{patient.name}</p><p className="mt-1 text-[11px] font-medium text-slate-400">{patient.id} · آخر زيارة {formatArabicDate(patient.lastVisit)}</p></div><StatusBadge value={patient.status} /></button>)}</div>{filtered.length === 0 && <div className="p-12 text-center text-sm font-bold text-slate-400">لا توجد نتائج مطابقة.</div>}</div>{selected && <PatientDrawer patient={selected} onClose={() => setSelected(null)} />}</div>; }
function PatientDrawer({ patient, onClose }) { return <div className="fixed inset-0 z-40 flex justify-start bg-slate-950/30 backdrop-blur-sm" onClick={onClose}><aside onClick={(event) => event.stopPropagation()} className="h-full w-full max-w-md overflow-y-auto bg-white p-6 shadow-2xl sm:p-8"><div className="flex items-start justify-between"><div className="flex items-center gap-3"><Avatar name={patient.name} tone="teal" /><div><h2 className="text-lg font-extrabold text-slate-900">{patient.name}</h2><p className="mt-1 font-mono text-xs font-bold text-slate-400">{patient.id}</p></div></div><button onClick={onClose} className="icon-button"><X size={18} /></button></div><div className="mt-8 grid grid-cols-2 gap-3"><div className="detail-tile"><span>العمر</span><strong>{patient.age} سنة</strong></div><div className="detail-tile"><span>فصيلة الدم</span><strong className="text-rose-600">{patient.bloodType}</strong></div><div className="detail-tile"><span>الجوال</span><strong dir="ltr">+{patient.phone}</strong></div><div className="detail-tile"><span>آخر زيارة</span><strong>{formatArabicDate(patient.lastVisit)}</strong></div></div><div className="mt-7"><h3 className="section-title">ملخص الحالة</h3><div className="mt-3 rounded-2xl bg-slate-50 p-4 text-sm font-medium leading-7 text-slate-600">المريض مسجل ضمن برنامج المتابعة الدورية. يرجى مراجعة العلامات الحيوية والتحاليل عند الزيارة القادمة.</div></div><div className="mt-7"><h3 className="section-title">التشخيصات المسجلة</h3><div className="mt-3 flex flex-wrap gap-2">{patient.tags.map((tag) => <span key={tag} className="tag-pill tag-pill-large">{tag}</span>)}</div></div><div className="mt-8 flex gap-2"><button onClick={() => openWhatsApp(patient.phone, `مرحباً ${patient.name}، هذه رسالة من مركز نبض الطبي.`)} className="primary-button flex-1"><MessageCircle size={16} /> واتساب</button><button className="secondary-button"><Paperclip size={16} /> مرفقات</button></div></aside></div>; }

function BookingForm({ data, onSave, onCancel }) { const [form, setForm] = useState({ patientId: data.patients[0]?.id || "", time: "14:00", type: "متابعة عامة", doctor: "د. ليان السالم" }); const patient = data.patients.find((item) => item.id === form.patientId); const submit = (event) => { event.preventDefault(); if (!patient) return; onSave({ id: `AP-${2206 + Math.floor(Math.random() * 90)}`, patientId: patient.id, patientName: patient.name, phone: patient.phone, date: "2026-09-24", status: "مؤكد", ...form }); }; return <form onSubmit={submit} className="panel booking-panel"><div className="flex items-center justify-between"><div><h3 className="section-title">حجز موعد جديد</h3><p className="section-subtitle">سيظهر الموعد فوراً في جدول اليوم.</p></div><button type="button" onClick={onCancel} className="icon-button"><X size={17} /></button></div><div className="mt-5 grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><label className="field-label">المريض<select className="input mt-2" value={form.patientId} onChange={(event) => setForm({ ...form, patientId: event.target.value })}>{data.patients.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label className="field-label">الوقت<input type="time" className="input mt-2" value={form.time} onChange={(event) => setForm({ ...form, time: event.target.value })} /></label><label className="field-label">نوع الزيارة<select className="input mt-2" value={form.type} onChange={(event) => setForm({ ...form, type: event.target.value })}><option>متابعة عامة</option><option>استشارة قلب</option><option>فحص دوري</option><option>مراجعة تحاليل</option></select></label><label className="field-label">الطبيب<select className="input mt-2" value={form.doctor} onChange={(event) => setForm({ ...form, doctor: event.target.value })}><option>د. ليان السالم</option><option>د. رامي الحربي</option></select></label></div><button className="primary-button mt-4">تأكيد الحجز <Check size={16} /></button></form>; }
function AppointmentsView({ data, onAdd, onStatus }) { const [showBooking, setShowBooking] = useState(false); const days = ["السبت", "الأحد", "الاثنين", "الثلاثاء", "الأربعاء", "الخميس", "الجمعة"]; return <div className="space-y-5 animate-enter"><div className="panel flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between"><div><div className="flex items-center gap-2"><h2 className="section-title">الخميس، 24 سبتمبر</h2></div><p className="section-subtitle mt-1">جدول العيادة · {data.appointments.length} مواعيد اليوم</p></div><div className="flex gap-2"><button onClick={() => setShowBooking((value) => !value)} className="primary-button"><Plus size={16} /> حجز موعد</button></div></div>{showBooking && <BookingForm data={data} onCancel={() => setShowBooking(false)} onSave={(appointment) => { onAdd(appointment); setShowBooking(false); }} />}<div className="panel overflow-hidden p-0"><div className="flex items-center justify-between border-b border-slate-100 px-4 py-3"><div className="flex w-full gap-1 overflow-x-auto">{days.map((day, index) => <button key={day} className={`day-chip ${index === 5 ? "day-chip-active" : ""}`}><span>{day}</span><strong>{18 + index}</strong></button>)}</div></div><div className="p-4"><div className="grid gap-3">{data.appointments.map((appointment, index) => <div key={appointment.id} className={`schedule-card ${appointment.status === "ملغي" ? "schedule-card-muted" : ""}`}><div className="flex w-16 flex-col items-center justify-center border-l border-slate-100 pl-3"><span className="text-sm font-extrabold text-slate-800">{appointment.time}</span><span className="mt-1 text-[10px] font-bold text-slate-400">30 دقيقة</span></div><Avatar name={appointment.patientName} tone={["teal", "blue", "amber", "purple"][index % 4]} /><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><p className="truncate text-sm font-extrabold text-slate-800">{appointment.patientName}</p><StatusBadge value={appointment.status} /></div><p className="mt-1 text-xs font-medium text-slate-400">{appointment.type} · {appointment.doctor}</p></div><div className="flex items-center gap-2"><button onClick={() => openWhatsApp(appointment.phone, `مرحباً ${appointment.patientName}، نذكركم بموعدكم اليوم الساعة ${appointment.time} في مركز نبض الطبي.`)} className="icon-button"><MessageCircle size={16} /></button><select aria-label="حالة الموعد" value={appointment.status} onChange={(event) => onStatus(appointment.id, event.target.value)} className="status-select"><option>مؤكد</option><option>في الانتظار</option><option>ملغي</option></select></div></div>)}</div></div></div></div>; }

function printMedicalBill(bill, clinic) {
  const html = `<html dir="rtl" lang="ar"><head><meta charset="utf-8"><title>${bill.id} - ${clinic.name}</title><style>body{font-family:Arial,sans-serif;color:#172033;padding:40px;direction:rtl}header{border-bottom:2px solid #0f766e;padding-bottom:16px;margin-bottom:24px}h1{color:#0f766e;margin:0 0 6px}table{width:100%;border-collapse:collapse;margin-top:24px}td,th{border:1px solid #d9e2e8;padding:12px;text-align:right}th{background:#effaf8}.total{font-size:20px;font-weight:bold;margin-top:24px}.muted{color:#64748b}</style></head><body><header><h1>${clinic.name}</h1><div>${clinic.specialty} · ${clinic.phone}</div></header><h2>مستند حساب طبي</h2><p>رقم المستند: <b>${bill.id}</b></p><p>المريض: <b>${bill.patient}</b> · رقم الملف: ${bill.patientId}</p><table><tr><th>نوع الحساب</th><th>التفاصيل</th><th>التاريخ</th><th>المبلغ</th></tr><tr><td>${bill.category || "كشف / زيارة"}</td><td>${bill.service}</td><td>${formatArabicDate(bill.date)}</td><td>${bill.amount.toLocaleString("ar-SA")} ر.س</td></tr></table><p class="total">الإجمالي: ${bill.amount.toLocaleString("ar-SA")} ر.س</p><p class="muted">يمكن اختيار «حفظ كملف PDF» من نافذة الطباعة.</p><script>window.onload=function(){window.print()}</script></body></html>`;
  openPrintableHtml(html, "مستند حساب طبي");
}

function BillingForm({ data, onSave, onCancel }) { const [form, setForm] = useState({ patientId: data.patients[0]?.id || "", category: "كشف / زيارة", service: "كشف طبي", amount: "150" }); const patient = data.patients.find((item) => item.id === form.patientId); const categoryServices = { "كشف / زيارة": "كشف طبي", "خروج": "كشف خروج ومتابعة", "تحاليل": "تحاليل مخبرية" }; const changeCategory = (category) => setForm({ ...form, category, service: categoryServices[category] }); const submit = (event) => { event.preventDefault(); if (!patient || !Number(form.amount)) return; onSave({ id: `INV-${7843 + Math.floor(Math.random() * 80)}`, patient: patient.name, patientId: patient.id, date: "2026-09-24", amount: Number(form.amount), status: "معلقة", category: form.category, service: form.service }); }; return <form onSubmit={submit} className="panel billing-form"><div className="flex items-center justify-between"><div><h3 className="section-title">إنشاء حساب طبي</h3><p className="section-subtitle">اختر نوع المستند؛ التحاليل لها حساب مستقل عن كشف الزيارة.</p></div><button type="button" onClick={onCancel} className="icon-button"><X size={17} /></button></div><div className="mt-5 grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><label className="field-label">المريض<select className="input mt-2" value={form.patientId} onChange={(event) => setForm({ ...form, patientId: event.target.value })}>{data.patients.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label className="field-label">نوع الحساب<select className="input mt-2" value={form.category} onChange={(event) => changeCategory(event.target.value)}><option>كشف / زيارة</option><option>خروج</option><option>تحاليل</option></select></label><label className="field-label">التفاصيل<input className="input mt-2" value={form.service} onChange={(event) => setForm({ ...form, service: event.target.value })} /></label><label className="field-label">المبلغ<input type="number" min="0" className="input mt-2" value={form.amount} onChange={(event) => setForm({ ...form, amount: event.target.value })} /></label></div><button className="primary-button mt-4"><Plus size={16} /> حفظ الحساب الطبي</button></form>; }

function BillingView({ data, onAdd, onToast }) { const [showForm, setShowForm] = useState(false); const [filter, setFilter] = useState("الكل"); const filtered = filter === "الكل" ? data.bills : data.bills.filter((bill) => (bill.category || "كشف / زيارة") === filter); const total = filtered.reduce((sum, bill) => sum + bill.amount, 0); const collected = filtered.filter((bill) => bill.status === "مدفوعة").reduce((sum, bill) => sum + bill.amount, 0); return <div className="space-y-5 animate-enter"><div className="grid gap-4 sm:grid-cols-3"><StatCard label="إجمالي الحسابات" value={`${total.toLocaleString("ar-SA")} ر.س`} delta="الكل" icon={ReceiptText} tone="teal" note="ضمن الفلتر الحالي" /><StatCard label="المحصّل" value={`${collected.toLocaleString("ar-SA")} ر.س`} delta="مدفوع" icon={Check} tone="blue" note="حسابات مكتملة" /><StatCard label="قيد التحصيل" value={`${(total - collected).toLocaleString("ar-SA")} ر.س`} delta="معلق" icon={Clock3} tone="amber" note="يمكن طباعتها أو إرسالها" /></div><div className="panel billing-intro"><div><h2 className="section-title">الحسابات الطبية</h2><p className="section-subtitle">مستند مستقل للكشف، الخروج، والتحاليل بدلاً من فاتورة مبيعات عامة.</p></div><button onClick={() => setShowForm((value) => !value)} className="primary-button"><Plus size={16} /> حساب طبي جديد</button></div>{showForm && <BillingForm data={data} onCancel={() => setShowForm(false)} onSave={(bill) => { onAdd(bill); setShowForm(false); onToast("تم حفظ الحساب الطبي"); }} />}<div className="panel p-0"><div className="billing-filters"><div><p className="text-sm font-extrabold text-slate-800">سجل الحسابات</p><p className="mt-1 text-[11px] font-medium text-slate-400">اضغط «طباعة / PDF» لتسليم كشف حساب للمريض.</p></div><div className="flex flex-wrap gap-2">{["الكل", "كشف / زيارة", "خروج", "تحاليل"].map((item) => <button key={item} onClick={() => setFilter(item)} className={`filter-chip ${filter === item ? "filter-chip-active" : ""}`}>{item}</button>)}</div></div><div className="overflow-x-auto"><table className="data-table"><thead><tr><th>رقم المستند</th><th>المريض</th><th>النوع</th><th>التفاصيل</th><th>التاريخ</th><th>المبلغ</th><th>الإجراء</th></tr></thead><tbody>{filtered.map((bill) => <tr key={bill.id}><td><span className="font-mono text-xs font-extrabold text-teal-700">{bill.id}</span></td><td><p className="text-sm font-extrabold text-slate-800">{bill.patient}</p><p className="font-mono text-[10px] text-slate-400">{bill.patientId}</p></td><td><span className={`medical-type medical-type-${bill.category === "تحاليل" ? "lab" : bill.category === "خروج" ? "discharge" : "visit"}`}>{bill.category || "كشف / زيارة"}</span></td><td><span className="text-xs font-bold text-slate-600">{bill.service}</span></td><td><span className="text-xs font-bold text-slate-500">{formatArabicDate(bill.date)}</span></td><td><span className="text-sm font-extrabold text-slate-900">{bill.amount.toLocaleString("ar-SA")} ر.س</span></td><td><div className="flex gap-2"><button onClick={() => printMedicalBill(bill, data.clinic)} className="icon-button" title="طباعة أو حفظ PDF"><FileDown size={16} /></button><button onClick={() => openWhatsApp("966501234567", `مرحباً ${bill.patient}، هذا مستند حساب ${bill.id} بقيمة ${bill.amount} ر.س من ${data.clinic.name}.`)} className="icon-button" title="إرسال عبر واتساب"><MessageCircle size={16} /></button></div></td></tr>)}</tbody></table></div>{filtered.length === 0 && <div className="p-12 text-center text-sm font-bold text-slate-400">لا توجد حسابات من هذا النوع.</div>}</div></div>; }

function PrescriptionsView({ data }) { return <div className="space-y-5 animate-enter"><div className="panel flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between"><div><h2 className="section-title">الروشتات والتقارير الطبية</h2><p className="section-subtitle">قوالب PDF مخصصة باسم العيادة مع بيانات المريض والطبيب والتوقيع.</p></div><button className="primary-button"><Plus size={16} /> روشتة جديدة</button></div><div className="grid gap-4 lg:grid-cols-2">{data.prescriptions.map((prescription, index) => { const patient = data.patients.find((item) => item.name === prescription.patient); return <div key={prescription.id} className="panel prescription-card"><div className="flex items-start justify-between"><div className="flex items-center gap-3"><span className={`prescription-icon prescription-icon-${index % 3}`}><FileText size={20} /></span><div><p className="text-sm font-extrabold text-slate-900">{prescription.patient}</p><p className="mt-1 text-xs font-medium text-slate-400">{prescription.id} · {formatArabicDate(prescription.date)}</p></div></div><button className="icon-button"><MoreHorizontal size={17} /></button></div><div className="mt-5 grid grid-cols-2 gap-3"><div className="rounded-xl bg-slate-50 p-3"><p className="text-[10px] font-bold text-slate-400">التشخيص</p><p className="mt-1 text-xs font-extrabold text-slate-700">{prescription.diagnosis}</p></div><div className="rounded-xl bg-slate-50 p-3"><p className="text-[10px] font-bold text-slate-400">الأدوية</p><p className="mt-1 text-xs font-extrabold text-slate-700">{prescription.medicines} أدوية موصوفة</p></div></div><div className="mt-5 flex flex-wrap items-center justify-between gap-2 border-t border-slate-100 pt-4"><span className="text-xs font-bold text-slate-400">{prescription.doctor}</span><div className="flex flex-wrap gap-2"><button onClick={() => printMedicalDocument("prescription", prescription, data.clinic, patient)} className="secondary-button"><FileDown size={15} /> روشتة PDF</button><button onClick={() => printMedicalDocument("report", prescription, data.clinic, patient)} className="secondary-button"><FileText size={15} /> تقرير PDF</button><button onClick={() => openWhatsApp("966501234567", `مرحباً ${prescription.patient}، يمكنكم مراجعة الروشتة ${prescription.id} عبر مركز نبض الطبي.`)} className="icon-button" title="مشاركة واتساب"><MessageCircle size={15} /></button></div></div></div>; })}</div></div>; }
function DiagnosisForm({ data, onSave, onCancel }) {
  const [form, setForm] = useState({ patientId: data.patients[0]?.id || "", chiefComplaint: "", diagnosis: "", bloodPressure: "", pulse: "", temperature: "", weight: "", oxygen: "", examination: "", labResults: "", plan: "", medications: "", followUpDate: "", followUpTime: "09:00", followUpTitle: "مراجعة طبية" });
  const patient = data.patients.find((item) => item.id === form.patientId);
  const update = (key, value) => setForm((current) => ({ ...current, [key]: value }));
  const submit = (event) => {
    event.preventDefault();
    if (!patient || !form.diagnosis.trim()) return;
    onSave({ id: `MR-${1002 + Math.floor(Math.random() * 8998)}`, patientId: patient.id, patientName: patient.name, doctor: "د. ليان السالم", date: new Date().toISOString().slice(0, 10), chiefComplaint: form.chiefComplaint.trim(), diagnosis: form.diagnosis.trim(), vitalSigns: { bloodPressure: form.bloodPressure, pulse: form.pulse, temperature: form.temperature, weight: form.weight, oxygen: form.oxygen }, examination: form.examination.trim(), labResults: form.labResults.trim(), plan: form.plan.trim(), medications: form.medications.trim(), followUpDate: form.followUpDate, followUpTime: form.followUpTime, followUpTitle: form.followUpTitle.trim() });
  };
  return <form onSubmit={submit} className="panel space-y-5"><div className="flex items-center justify-between"><div><h3 className="section-title">إضافة تشخيص وفحص جديد</h3><p className="section-subtitle">تُحفظ كل الحقول تلقائياً داخل سجل المريض على هذا الجهاز.</p></div><button type="button" onClick={onCancel} className="icon-button"><X size={17} /></button></div><div className="grid gap-3 sm:grid-cols-2"><label className="field-label">المريض<select className="input mt-2" value={form.patientId} onChange={(event) => update("patientId", event.target.value)}>{data.patients.map((item) => <option key={item.id} value={item.id}>{item.name} · {item.id}</option>)}</select></label><label className="field-label">الشكوى الرئيسية<input className="input mt-2" value={form.chiefComplaint} onChange={(event) => update("chiefComplaint", event.target.value)} placeholder="سبب الزيارة أو الأعراض" /></label></div><label className="field-label block">التشخيص الطبي *<input required className="input mt-2" value={form.diagnosis} onChange={(event) => update("diagnosis", event.target.value)} placeholder="التشخيص المبدئي أو النهائي" /></label><div><p className="field-label">العلامات الحيوية</p><div className="mt-2 grid gap-3 grid-cols-2 sm:grid-cols-5"><label className="field-label">ضغط الدم<input className="input mt-2" dir="ltr" value={form.bloodPressure} onChange={(event) => update("bloodPressure", event.target.value)} placeholder="120/80" /></label><label className="field-label">النبض<input className="input mt-2" dir="ltr" value={form.pulse} onChange={(event) => update("pulse", event.target.value)} placeholder="72" /></label><label className="field-label">الحرارة<input className="input mt-2" dir="ltr" value={form.temperature} onChange={(event) => update("temperature", event.target.value)} placeholder="36.8" /></label><label className="field-label">الوزن<input className="input mt-2" dir="ltr" value={form.weight} onChange={(event) => update("weight", event.target.value)} placeholder="kg" /></label><label className="field-label">الأكسجين<input className="input mt-2" dir="ltr" value={form.oxygen} onChange={(event) => update("oxygen", event.target.value)} placeholder="98%" /></label></div></div><div className="grid gap-3 lg:grid-cols-2"><label className="field-label">نتيجة الفحص السريري<textarea className="input mt-2 min-h-24" value={form.examination} onChange={(event) => update("examination", event.target.value)} placeholder="سجّل الملاحظات والنتائج السريرية بالتفصيل" /></label><label className="field-label">نتائج التحاليل والفحوصات<textarea className="input mt-2 min-h-24" value={form.labResults} onChange={(event) => update("labResults", event.target.value)} placeholder="اسم الفحص، النتيجة، الوحدة، والمجال المرجعي" /></label><label className="field-label">خطة العلاج والمتابعة<textarea className="input mt-2 min-h-24" value={form.plan} onChange={(event) => update("plan", event.target.value)} placeholder="التوصيات وموعد المراجعة" /></label><label className="field-label">الأدوية والتعليمات<textarea className="input mt-2 min-h-24" value={form.medications} onChange={(event) => update("medications", event.target.value)} placeholder="اسم الدواء والجرعة والتعليمات" /></label></div><div className="grid gap-3 rounded-2xl border border-amber-100 bg-amber-50/50 p-4 sm:grid-cols-3"><label className="field-label sm:col-span-2">موعد المراجعة القادمة<input type="date" className="input mt-2" value={form.followUpDate} onChange={(event) => update("followUpDate", event.target.value)} /></label><label className="field-label">الوقت<input type="time" className="input mt-2" value={form.followUpTime} onChange={(event) => update("followUpTime", event.target.value)} /></label><label className="field-label sm:col-span-3">عنوان التذكير<input className="input mt-2" value={form.followUpTitle} onChange={(event) => update("followUpTitle", event.target.value)} placeholder="مراجعة نتائج التحاليل" /></label></div><div className="flex flex-wrap gap-2"><button type="submit" className="primary-button"><Check size={16} /> حفظ التشخيص في ملف المريض</button><button type="button" onClick={onCancel} className="secondary-button">إلغاء</button></div></form>;
}

function shareMedicalRecordByEmail(record, patient, clinic) {
  const email = patient?.email || window.prompt("أدخل بريد المريض لإعداد رسالة التقرير");
  if (!email?.trim()) return;
  const subject = `تقرير الفحوصات الطبية ${record.id} - ${clinic.name}`;
  const body = `مرحباً ${record.patientName}،\n\nتم تجهيز تقرير الفحوصات الطبية رقم ${record.id}.\nالتشخيص: ${record.diagnosis || "غير مسجل"}\nتاريخ الفحص: ${record.date}\n\nيمكن إرفاق ملف PDF الذي تم تصديره من التطبيق بهذه الرسالة.`;
  window.location.href = `mailto:${encodeURIComponent(email.trim())}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
}

function DiagnosisView({ data, onSave, onToast }) {
  const [showForm, setShowForm] = useState(false);
  const [patientFilter, setPatientFilter] = useState("الكل");
  const records = data.medicalRecords || [];
  const filtered = patientFilter === "الكل" ? records : records.filter((record) => record.patientId === patientFilter);
  return <div className="space-y-5 animate-enter"><div className="grid gap-4 sm:grid-cols-3"><StatCard label="إجمالي السجلات الطبية" value={records.length.toLocaleString("ar-SA")} delta="محفوظ" icon={Stethoscope} tone="teal" note="تشخيصات وفحوصات موثقة" /><StatCard label="المرضى المشمولون" value={new Set(records.map((record) => record.patientId)).size.toLocaleString("ar-SA")} delta="ملفات" icon={UsersRound} tone="blue" note="لديهم سجل تشخيص" /><StatCard label="سجلات هذا الشهر" value={records.filter((record) => String(record.date).startsWith("2026-09")).length.toLocaleString("ar-SA")} delta="جديد" icon={FileText} tone="purple" note="قابلة للمراجعة" /></div><div className="panel flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between"><div><h2 className="section-title">سجل التشخيص والفحوصات</h2><p className="section-subtitle">كل زيارة تجمع بيانات المريض، العلامات الحيوية، التحاليل، التشخيص، والخطة العلاجية.</p></div><button onClick={() => setShowForm((value) => !value)} className="primary-button"><Plus size={16} /> تشخيص جديد</button></div>{showForm && <DiagnosisForm data={data} onCancel={() => setShowForm(false)} onSave={(record) => { onSave(record); setShowForm(false); onToast("تم حفظ التشخيص وجميع بيانات الفحص"); }} />}<div className="panel p-0"><div className="flex flex-col gap-3 border-b border-slate-100 p-4 sm:flex-row sm:items-center sm:justify-between"><div><p className="text-sm font-extrabold text-slate-800">السجلات المحفوظة</p><p className="mt-1 text-[11px] font-medium text-slate-400">يمكن تصفية السجلات حسب المريض.</p></div><select className="input max-w-xs" value={patientFilter} onChange={(event) => setPatientFilter(event.target.value)}><option value="الكل">كل المرضى</option>{data.patients.map((patient) => <option key={patient.id} value={patient.id}>{patient.name}</option>)}</select></div><div className="grid gap-4 p-4 lg:grid-cols-2">{filtered.map((record) => <article key={record.id} className="rounded-2xl border border-slate-100 bg-white p-4 shadow-sm"><div className="flex items-start justify-between gap-3"><div><p className="text-sm font-extrabold text-slate-900">{record.patientName}</p><p className="mt-1 font-mono text-[10px] font-bold text-slate-400">{record.id} · {formatArabicDate(record.date)}</p></div><span className="medical-type medical-type-visit">تشخيص</span></div><div className="mt-4 grid gap-3 sm:grid-cols-2"><div className="rounded-xl bg-teal-50 p-3"><p className="text-[10px] font-bold text-teal-700">التشخيص</p><p className="mt-1 text-xs font-extrabold leading-5 text-slate-800">{record.diagnosis}</p></div><div className="rounded-xl bg-slate-50 p-3"><p className="text-[10px] font-bold text-slate-400">الشكوى الرئيسية</p><p className="mt-1 text-xs font-bold leading-5 text-slate-700">{record.chiefComplaint || "غير مسجلة"}</p></div></div><div className="mt-3 flex flex-wrap gap-2">{Object.entries(record.vitalSigns || {}).filter(([, value]) => value).map(([key, value]) => <span key={key} className="tag-pill">{({ bloodPressure: "ضغط", pulse: "نبض", temperature: "حرارة", weight: "وزن", oxygen: "أكسجين" })[key]}: {value}</span>)}</div><div className="mt-4 space-y-2 border-t border-slate-100 pt-3 text-xs leading-6 text-slate-600"><p><strong className="text-slate-800">الفحص:</strong> {record.examination || "غير مسجل"}</p><p><strong className="text-slate-800">التحاليل:</strong> {record.labResults || "غير مسجلة"}</p><p><strong className="text-slate-800">الخطة:</strong> {record.plan || "غير مسجلة"}</p></div><div className="mt-4 flex flex-wrap items-center justify-between gap-2 border-t border-slate-100 pt-3"><p className="text-[11px] font-bold text-slate-400">الطبيب المعالج: {record.doctor}</p><div className="flex flex-wrap gap-2"><button onClick={() => printMedicalRecordReport(record, data.clinic, data.patients.find((patient) => patient.id === record.patientId))} className="secondary-button"><FileDown size={15} /> PDF</button><button onClick={() => openWhatsApp(data.patients.find((patient) => patient.id === record.patientId)?.phone, `مرحباً ${record.patientName}، هذا رابط متابعة تقرير الفحوصات ${record.id} من ${data.clinic.name}. يرجى مراجعة العيادة عند الحاجة.`)} className="secondary-button"><MessageCircle size={15} /> واتساب</button><button onClick={() => shareMedicalRecordByEmail(record, data.patients.find((patient) => patient.id === record.patientId), data.clinic)} className="secondary-button"><Mail size={15} /> بريد</button></div></div></article>)}</div>{filtered.length === 0 && <div className="p-12 text-center text-sm font-bold text-slate-400">لا توجد سجلات تشخيص مطابقة.</div>}</div></div>;
}

function ReminderView({ data, onStatus, onToast }) {
  const reminders = data.reminders || [];
  const now = new Date();
  const getDate = (reminder) => new Date(`${reminder.date}T${reminder.time || "09:00"}`);
  const activeReminders = reminders.filter((reminder) => reminder.status !== "done").sort((a, b) => getDate(a) - getDate(b));
  const sendReminder = (reminder) => { openWhatsApp(reminder.phone, `مرحباً ${reminder.patientName}، نذكركم بموعد ${reminder.title} بتاريخ ${formatArabicDate(reminder.date)} الساعة ${reminder.time || "09:00"} في ${data.clinic.name}.`); onToast("تم فتح رسالة التذكير في واتساب"); };
  useEffect(() => {
    if (typeof Notification === "undefined" || Notification.permission !== "granted") return;
    activeReminders.filter((reminder) => getDate(reminder) <= now).forEach((reminder) => {
      const key = `clinic-notified-${reminder.id}-${reminder.date}`;
      if (!sessionStorage.getItem(key)) { new Notification("تذكير مراجعة", { body: `${reminder.patientName} · ${reminder.title}` }); sessionStorage.setItem(key, "1"); }
    });
  }, [activeReminders.length]);
  const enableNotifications = async () => { if (typeof Notification === "undefined") { onToast("المتصفح لا يدعم إشعارات النظام"); return; } const permission = await Notification.requestPermission(); onToast(permission === "granted" ? "تم تفعيل إشعارات المراجعة" : "لم يتم السماح بالإشعارات"); };
  return <div className="space-y-5 animate-enter"><div className="panel flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between"><div><div className="flex items-center gap-2"><span className="stat-icon stat-icon-amber"><Bell size={19} /></span><div><h2 className="section-title">تذكيرات المراجعة</h2><p className="section-subtitle">تظهر التنبيهات عند فتح التطبيق، ويمكن إرسال تذكير مباشر للمريض.</p></div></div></div><button onClick={enableNotifications} className="secondary-button"><Bell size={15} /> تفعيل إشعارات الجهاز</button></div><div className="grid gap-4 sm:grid-cols-3"><StatCard label="كل التذكيرات" value={reminders.length.toLocaleString("ar-SA")} delta="محفوظ" icon={Bell} tone="amber" note="في سجل العيادة" /><StatCard label="القادمة" value={activeReminders.filter((reminder) => getDate(reminder) > now).length.toLocaleString("ar-SA")} delta="موعد" icon={CalendarDays} tone="blue" note="تحتاج متابعة" /><StatCard label="المتأخرة" value={activeReminders.filter((reminder) => getDate(reminder) <= now).length.toLocaleString("ar-SA")} delta="تنبيه" icon={Clock3} tone="purple" note="يرجى التواصل" /></div><div className="panel p-0"><div className="border-b border-slate-100 p-4"><p className="text-sm font-extrabold text-slate-800">جدول التذكيرات</p><p className="mt-1 text-[11px] font-medium text-slate-400">يتم إنشاء التذكير تلقائياً عند إضافة موعد مراجعة في تشخيص الطبيب.</p></div><div className="divide-y divide-slate-100">{activeReminders.map((reminder) => { const overdue = getDate(reminder) <= now; return <div key={reminder.id} className="flex flex-col gap-3 p-4 sm:flex-row sm:items-center"><span className={`grid h-11 w-11 shrink-0 place-items-center rounded-2xl ${overdue ? "bg-rose-50 text-rose-600" : "bg-amber-50 text-amber-600"}`}><Bell size={19} /></span><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><p className="text-sm font-extrabold text-slate-800">{reminder.patientName}</p><span className={overdue ? "badge-danger status-badge" : "badge-warning status-badge"}>{overdue ? "متأخر" : "قادم"}</span></div><p className="mt-1 text-xs font-bold text-slate-500">{reminder.title}</p><p className="mt-1 text-[11px] font-medium text-slate-400">{formatArabicDate(reminder.date)} · {reminder.time || "09:00"} · {reminder.phone}</p></div><div className="flex flex-wrap gap-2"><button onClick={() => sendReminder(reminder)} className="secondary-button"><MessageCircle size={15} /> واتساب</button><button onClick={() => { onStatus(reminder.id, "done"); onToast("تم إكمال التذكير"); }} className="secondary-button"><Check size={15} /> تم</button></div></div>; })}</div>{activeReminders.length === 0 && <div className="p-12 text-center text-sm font-bold text-slate-400">لا توجد تذكيرات نشطة.</div>}</div></div>;
}

function SettingsView({ data, onReset, onLogoChange, onSignatureChange }) { const readImage = (event, callback, label) => { const file = event.target.files?.[0]; if (!file) return; if (file.size > 2 * 1024 * 1024) { window.alert(`حجم ${label} يجب ألا يتجاوز 2MB`); return; } const reader = new FileReader(); reader.onload = () => callback(String(reader.result || "")); reader.readAsDataURL(file); }; return <div className="space-y-5 animate-enter"><div className="panel"><div className="flex items-center gap-3"><span className="grid h-11 w-11 place-items-center rounded-2xl bg-teal-50 text-teal-700"><Settings2 size={21} /></span><div><h2 className="section-title">بيانات العيادة</h2><p className="section-subtitle">تظهر هذه المعلومات في رسائل الواتساب والمستندات الطبية.</p></div></div><div className="mt-7 grid gap-4 sm:grid-cols-2"><label className="field-label">اسم العيادة<input value={data.clinic.name} readOnly className="input mt-2" /></label><label className="field-label">التخصص<input value={data.clinic.specialty} readOnly className="input mt-2" /></label><label className="field-label">الهاتف<input value={data.clinic.phone} readOnly className="input mt-2" dir="ltr" /></label><label className="field-label">العنوان<input value={data.clinic.address} readOnly className="input mt-2" /></label></div><div className="logo-settings mt-6"><div><p className="text-sm font-extrabold text-slate-800">شعار العيادة</p><p className="mt-1 text-xs font-medium leading-5 text-slate-400">ارفع صورة PNG أو JPG بحد أقصى 2MB، وستظهر تلقائياً في رأس الروشتات والتقارير PDF.</p><div className="mt-3 flex flex-wrap gap-2"><label className="primary-button cursor-pointer"><ImagePlus size={16} /> {data.clinic.logo ? "تغيير الشعار" : "رفع الشعار"}<input type="file" accept="image/png,image/jpeg,image/webp" className="hidden" onChange={(event) => readImage(event, onLogoChange, "الشعار")} /></label>{data.clinic.logo && <button onClick={() => onLogoChange("")} className="secondary-button">حذف الشعار</button>}</div></div><div className="logo-preview">{data.clinic.logo ? <img src={data.clinic.logo} alt="معاينة شعار العيادة" /> : <span><ImagePlus size={22} /> بدون شعار</span>}</div></div><div className="logo-settings mt-4"><div><p className="text-sm font-extrabold text-slate-800">توقيع الطبيب الإلكتروني</p><p className="mt-1 text-xs font-medium leading-5 text-slate-400">ارفع صورة التوقيع بخلفية بيضاء أو شفافة بحد أقصى 2MB، وستظهر أسفل اسم الطبيب في الروشتات والتقارير PDF.</p><div className="mt-3 flex flex-wrap gap-2"><label className="primary-button cursor-pointer"><ImagePlus size={16} /> {data.clinic.signature ? "تغيير التوقيع" : "رفع التوقيع"}<input type="file" accept="image/png,image/jpeg,image/webp" className="hidden" onChange={(event) => readImage(event, onSignatureChange, "التوقيع")} /></label>{data.clinic.signature && <button onClick={() => onSignatureChange("")} className="secondary-button">حذف التوقيع</button>}</div></div><div className="signature-preview">{data.clinic.signature ? <img src={data.clinic.signature} alt="معاينة توقيع الطبيب" /> : <span><FileText size={22} /> بدون توقيع</span>}</div></div><div className="mt-6 flex flex-wrap items-center justify-between gap-3 rounded-2xl bg-slate-50 p-4"><div><p className="text-sm font-extrabold text-slate-800">الحفظ التلقائي</p><p className="mt-1 text-xs font-medium text-slate-400">لا يحتاج الفريق إلى تفعيل المزامنة؛ كل التغييرات تُحفظ تلقائياً.</p></div><span className="status-badge badge-success"><Check size={13} /> يعمل تلقائياً</span></div></div><div className="panel"><h3 className="section-title">إجراءات الإدارة</h3><div className="mt-4 flex flex-wrap items-center justify-between gap-3 rounded-2xl border border-slate-100 p-4"><div><p className="text-sm font-extrabold text-slate-800">استعادة بيانات العرض</p><p className="mt-1 text-xs font-medium text-slate-400">يمسح التعديلات المحلية ويعيد البيانات الأولية.</p></div><button onClick={onReset} className="secondary-button"><FileText size={16} /> استعادة البيانات</button></div></div></div>; }

export default function App() {
  const [active, setActive] = useState("dashboard"); const [mobileOpen, setMobileOpen] = useState(false); const [cameraOpen, setCameraOpen] = useState(false); const [patientModal, setPatientModal] = useState(false); const [toast, setToast] = useState("");
  const { data, isOnline, addPatient, addAppointment, updateAppointmentStatus, addBill, addMedicalRecord, updateReminderStatus, updateClinicLogo, updateClinicSignature, resetDemo } = useClinicData(); const meta = PAGE_META[active] || PAGE_META.dashboard; const reminderCount = (data.reminders || []).filter((reminder) => reminder.status !== "done").length;
  useEffect(() => { document.documentElement.lang = "ar"; document.documentElement.dir = "rtl"; document.title = "عيادتي | نظام إدارة العيادة"; }, []);
  useEffect(() => { if (!toast) return undefined; const timer = window.setTimeout(() => setToast(""), 3000); return () => window.clearTimeout(timer); }, [toast]);
  useEffect(() => {
    const handleBack = (event) => {
      if (cameraOpen) { event.preventDefault(); setCameraOpen(false); return; }
      if (patientModal) { event.preventDefault(); setPatientModal(false); return; }
      if (mobileOpen) { event.preventDefault(); setMobileOpen(false); return; }
      if (active !== "dashboard") { event.preventDefault(); setActive("dashboard"); }
    };
    window.addEventListener("clinic:android-back", handleBack);
    return () => window.removeEventListener("clinic:android-back", handleBack);
  }, [active, cameraOpen, mobileOpen, patientModal]);
  const content = useMemo(() => { if (active === "patients") return <PatientsView data={data} onAdd={() => setPatientModal(true)} onCamera={() => setCameraOpen(true)} />; if (active === "diagnosis") return <DiagnosisView data={data} onSave={addMedicalRecord} onToast={setToast} />; if (active === "reminders") return <ReminderView data={data} onStatus={updateReminderStatus} onToast={setToast} />; if (active === "appointments") return <AppointmentsView data={data} onAdd={(appointment) => { addAppointment(appointment); setToast("تم حجز الموعد بنجاح"); }} onStatus={updateAppointmentStatus} />; if (active === "billing") return <BillingView data={data} onAdd={(bill) => addBill(bill)} onToast={setToast} />; if (active === "prescriptions") return <PrescriptionsView data={data} />; if (active === "settings") return <SettingsView data={data} onLogoChange={(logo) => { updateClinicLogo(logo); setToast(logo ? "تم حفظ شعار العيادة وسيظهر في ملفات PDF" : "تم حذف شعار العيادة"); }} onSignatureChange={(signature) => { updateClinicSignature(signature); setToast(signature ? "تم حفظ توقيع الطبيب وسيظهر في ملفات PDF" : "تم حذف توقيع الطبيب"); }} onReset={() => { resetDemo(); setToast("تمت استعادة البيانات التجريبية"); }} />; return <DashboardView data={data} onNavigate={setActive} onCamera={() => setCameraOpen(true)} />; }, [active, data, addAppointment, addBill, resetDemo, updateAppointmentStatus, addMedicalRecord, updateReminderStatus, updateClinicLogo, updateClinicSignature]);
  return <div className="min-h-screen bg-[#f6f9fc] text-slate-900"><Sidebar active={active} onNavigate={setActive} mobileOpen={mobileOpen} onClose={() => setMobileOpen(false)} isOnline={isOnline} reminderCount={reminderCount} /><main className="min-h-screen lg:mr-[268px]"><Header meta={meta} isOnline={isOnline} canGoBack={active !== "dashboard"} onBack={() => setActive("dashboard")} onMenu={() => setMobileOpen(true)} onCamera={() => setCameraOpen(true)} /><div className="px-4 py-6 sm:px-7 lg:px-10 lg:py-8">{content}</div></main>{cameraOpen && <CameraCapture onClose={() => setCameraOpen(false)} onCapture={({ type }) => { setToast(type === "qr" ? "تم التعرف على كود المريض" : "تم حفظ صورة الملف تلقائياً"); }} />}{patientModal && <PatientModal onClose={() => setPatientModal(false)} onSave={(patient) => { addPatient(patient); setPatientModal(false); setToast("تمت إضافة المريض إلى السجل"); }} />}{toast && <div className="toast"><span className="grid h-7 w-7 place-items-center rounded-lg bg-emerald-100 text-emerald-600"><Check size={15} /></span><span>{toast}</span></div>}</div>;
}
